const $=s=>document.querySelector(s),labels=['프롬프트 기초','AI 모델별 활용','게임/이미지 생성','무역 리서치','비즈니스 이메일','웹·개인 마케팅','심화·바이브 코딩'];let active=0,savedOnly=false,query='',selected=null;let bookmarks;try{bookmarks=new Set(JSON.parse(localStorage.getItem('prompt-world-saved')||'[]'))}catch{bookmarks=new Set()}
const all=sections.flatMap((s,si)=>s.cards.map((c,ci)=>({...c,si,ci,id:`${si}-${ci}`})));
const esc=s=>s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clean=s=>s.replace(/```\w*\n?/g,'').replace(/[#*`]/g,'').replace(/---/g,'').trim();
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2400)}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('프롬프트를 복사했어요. AI와 대화를 시작해보세요!')}catch{const t=document.createElement('textarea');t.value=text;document.body.append(t);t.select();const ok=document.execCommand('copy');t.remove();toast(ok?'복사했어요!':'복사를 지원하지 않는 환경입니다. 내용을 선택해 복사해주세요.')}}
function promptText(c){const blocks=[...c.body.matchAll(/```[^\n]*\n([\s\S]*?)```/g)].map(m=>m[1].trim());return blocks.length?blocks.join('\n\n'):clean(c.body)}
function toggle(id){bookmarks.has(id)?bookmarks.delete(id):bookmarks.add(id);try{localStorage.setItem('prompt-world-saved',JSON.stringify([...bookmarks]))}catch{toast('이 브라우저에서는 보관함을 영구 저장할 수 없어요.')}render()}
function render(){const list=all.filter(c=>((query||savedOnly)?true:(c.si===active||(active===2&&c.si===6&&c.title.includes('게임 플레이'))))&&(!savedOnly||bookmarks.has(c.id))&&(!query||(c.title+' '+c.body+' '+sections[c.si].title).toLowerCase().includes(query)));$('.tabs').innerHTML=labels.map((l,i)=>`<button role="tab" aria-selected="${i===active}" data-tab="${i}">${String(i+1).padStart(2,'0')} ${l}</button>`).join('');$('.subtopics').innerHTML=list.length?'<span class="subtopics-label">소제목 바로가기</span><div class="subtopics-list">'+list.map(c=>`<button data-jump="${c.id}">${esc(c.title)}</button>`).join('')+'</div>':'';$('#mission').textContent=String(active+1).padStart(2,'0');$('#sectionTitle').textContent=query?'전체 섹션 검색 결과':savedOnly?'나의 보관함':sections[active].title;$('#resultCount').textContent=`${list.length}개의 노트`;$('#saveCount').textContent=bookmarks.size;$('#onlySaved').classList.toggle('active',savedOnly);$('#onlySaved').setAttribute('aria-pressed',savedOnly);$('#cards').innerHTML=list.map(c=>`<article class="card" id="note-${c.id}" tabindex="-1"><div class="card-top"><span class="card-index">${query?esc(labels[c.si])+' / ':''}NOTE ${String(c.ci+1).padStart(2,'0')}</span><button class="bookmark ${bookmarks.has(c.id)?'selected':''}" data-save="${c.id}" aria-label="${esc(c.title)} 즐겨찾기" aria-pressed="${bookmarks.has(c.id)}">${bookmarks.has(c.id)?'★':'☆'}</button></div><h3>${esc(c.title)}</h3><p>${esc(clean(c.body).slice(0,220))}</p><div class="card-actions"><button data-open="${c.id}">내용 살펴보기 ↗</button><button class="copy" data-copy="${c.id}">프롬프트 복사 ⧉</button></div></article>`).join('');$('.empty').hidden=list.length!==0}
function show(id){selected=all.find(c=>c.id===id);$('#detail h2').textContent=selected.title;const parts=selected.body.split(/```[^\n]*\n([\s\S]*?)```/g);$('.detail-body').innerHTML=parts.map((p,i)=>i%2?`<pre>${esc(p.trim())}</pre>`:`<div class="prose">${esc(p.replace(/^---$/gm,'').trim())}</div>`).join('');$('#detail').showModal()}
document.addEventListener('click',e=>{const el=e.target.closest('button');if(!el)return;if(el.dataset.tab!==undefined){active=+el.dataset.tab;query='';$('#search').value='';render()}if(el.dataset.jump){const card=$('#note-'+el.dataset.jump);card.scrollIntoView({behavior:'smooth',block:'center'});card.focus({preventScroll:true})}if(el.dataset.save)toggle(el.dataset.save);if(el.dataset.open)show(el.dataset.open);if(el.dataset.copy)copy(promptText(all.find(c=>c.id===el.dataset.copy)))});
$('#search').addEventListener('input',e=>{query=e.target.value.trim().toLowerCase();render()});$('#onlySaved').onclick=()=>{savedOnly=!savedOnly;render()};$('#saved').onclick=()=>{savedOnly=true;query='';$('#search').value='';render();$('#library').scrollIntoView();toast('섹션별 즐겨찾기를 확인하세요. 검색하면 전체 섹션에서 찾아드려요.')};$('#reset').onclick=()=>{savedOnly=false;query='';$('#search').value='';render()};$('.close').onclick=()=>$('#detail').close();$('#detail').addEventListener('click',e=>{if(e.target===$('#detail')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});$('#detailCopy').onclick=()=>copy(promptText(selected));document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)&&!$('#detail').open){e.preventDefault();$('#search').focus();$('#library').scrollIntoView()}});$('.tabs').addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();active=e.key==='Home'?0:e.key==='End'?6:(active+(e.key==='ArrowRight'?1:6))%7;query='';$('#search').value='';render();$(`[data-tab="${active}"]`).focus()});$('#totalMeta').innerHTML=`${all.length} <small>바로 쓰는 실습 노트</small>`;render();
